import{_ as l,C as s,o as i,c as d,j as o,a as r,E as e,a3 as n}from"./chunks/framework.CZBGEXos.js";const f=JSON.parse('{"title":"Monitor","description":"","frontmatter":{},"headers":[],"relativePath":"ru/tools/monitor.md","filePath":"ru/tools/monitor.md"}'),h={name:"ru/tools/monitor.md"};function c(g,t,u,m,p,b){const a=s("Screenshot");return i(),d("div",null,[t[0]||(t[0]=o("h1",{id:"monitor",tabindex:"-1"},[r("Monitor "),o("a",{class:"header-anchor",href:"#monitor","aria-label":'Permalink to "Monitor"'},"​")],-1)),t[1]||(t[1]=o("p",null,[r("Monitor ранжирует весь рынок по метрике волатильности и держит верхушку этого рейтинга на экране. Если "),o("a",{href:"/manual/ru/tools/knives.html"},"Knives"),r(" ждёт, пока что-то пересечёт черту, и тогда сообщает, то Monitor — это непрерывно отсортированная таблица лидеров.")],-1)),t[2]||(t[2]=o("p",null,[r("Все показатели считаются по "),o("strong",null,"5-минутным свечам"),r(".")],-1)),e(a,{src:"monitor",alt:"Окно Monitor с ранжированными карточками тикеров",caption:"Окно Monitor"}),t[3]||(t[3]=n('<h2 id="как-читать-окно" tabindex="-1">Как читать окно <a class="header-anchor" href="#как-читать-окно" aria-label="Permalink to &quot;Как читать окно&quot;">​</a></h2><h3 id="заголовок-окна" tabindex="-1">Заголовок окна <a class="header-anchor" href="#заголовок-окна" aria-label="Permalink to &quot;Заголовок окна&quot;">​</a></h3><p>Заголовок — это живая сводка действующих сейчас настроек:</p><ul><li><strong>5m</strong> — таймфрейм свечей. Неизменный.</li><li><strong>NATR | Vol | Chg</strong> — активная сортировка. Это кнопки: нажмите, чтобы пересортировать, не открывая настройки.</li><li><strong>Детали сортировки</strong> — что именно делает текущая сортировка. Для NATR показывает метод сглаживания и режим агрегации (напр. <code>SMA · Weighted</code>); для Volume — источник и тип (напр. <code>Total · 75m</code>); для % Change — просто <code>% Change</code>. Если действует фильтр минимального объёма, к этому добавляется <code>min $&lt;сумма&gt;</code>.</li><li><strong>Пороги оповещений</strong> — <code>NATR ≥x% · % ≥y%</code>. Приглушены, когда звук оповещений выключен.</li><li><strong>Vol Ind</strong> — включает или выключает <a href="/manual/ru/customize/chart-colors.html#гистограмма-объема">гистограмму объёма</a> на графиках карточек.</li><li><strong>Иконки бирж</strong> — включённые биржи в порядке приоритета.</li><li><strong>Disconnected</strong> — показывается, если связь с данными оборвалась.</li></ul><h3 id="карточка-тикера" tabindex="-1">Карточка тикера <a class="header-anchor" href="#карточка-тикера" aria-label="Permalink to &quot;Карточка тикера&quot;">​</a></h3><p>Каждая карточка показывает тикер, биржи, где он торгуется, и три метрики:</p><table tabindex="0"><thead><tr><th>Метрика</th><th>Значение</th></tr></thead><tbody><tr><td><strong>NATR</strong></td><td>Волатильность — нормализованный средний истинный диапазон, на 5м свечах</td></tr><tr><td><strong>Volume</strong></td><td>Объём торгов в долларах за окно, заданное в <a href="#volume-type">Volume type</a></td></tr><tr><td><strong>% Change</strong></td><td>Изменение цены за 5 минут</td></tr></tbody></table><p>Наведение на логотип биржи показывает <code>Listed on &lt;биржа&gt;</code>. У карточек есть кнопка разворота, которая открывает полноэкранный график с теми же инструментами рисования, что и в <a href="/manual/ru/tools/analyzer.html#инструменты-рисования">Analyzer</a>.</p><h3 id="что-означают-цвета" tabindex="-1">Что означают цвета <a class="header-anchor" href="#что-означают-цвета" aria-label="Permalink to &quot;Что означают цвета&quot;">​</a></h3><p>Окраска управляется правилами <a href="#metric-colors">цветов метрик</a>, которые не связаны с порогами оповещений:</p><ul><li><strong>NATR</strong> переходит от цвета уровня 1 к цвету уровня 2, когда волатильность проходит каждый уровень.</li><li><strong>% Change</strong> окрашивается по направлению — одна пара цветов для роста, другая для падения — и так же повышается на уровне 2.</li></ul><p>Если динамические цвета для метрики выключены, она вместо этого просто подсвечивается при пересечении своего <strong>порога оповещения</strong>.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><p>Откройте вкладку <strong>Monitor</strong> в главном окне.</p>',14)),e(a,{src:"monitor-settings",alt:"Настройки сортировки Monitor",caption:"Настройки Monitor — сортировка"}),t[4]||(t[4]=n('<h3 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h3><h4 id="sort-by" tabindex="-1">Sort by <a class="header-anchor" href="#sort-by" aria-label="Permalink to &quot;Sort by&quot;">​</a></h4><p>Какая метрика ранжирует список: <strong>NATR</strong>, <strong>Volume</strong> или <strong>% Change</strong>. По умолчанию NATR.</p><h4 id="natr-method" tabindex="-1">NATR method <a class="header-anchor" href="#natr-method" aria-label="Permalink to &quot;NATR method&quot;">​</a></h4><p>Алгоритм сглаживания для расчёта NATR. По умолчанию <strong>SMA</strong>.</p><ul><li><strong>RMA</strong> — скользящее среднее Уайлдера. Глаже, медленнее реагирует.</li><li><strong>SMA</strong> — простое скользящее среднее. Чувствительнее к недавним свечам.</li></ul><h4 id="natr-aggregation" tabindex="-1">NATR aggregation <a class="header-anchor" href="#natr-aggregation" aria-label="Permalink to &quot;NATR aggregation&quot;">​</a></h4><p>Как получается одно значение NATR для тикера, который торгуется на нескольких биржах. По умолчанию <strong>Weighted</strong>.</p><ul><li><strong>Weighted</strong> — средневзвешенное по объёму по биржам.</li><li><strong>Highest</strong> — максимальный NATR среди всех бирж.</li><li><strong>Priority</strong> — значение с первой биржи в вашем порядке приоритета, у которой есть данные для этого тикера.</li></ul><h4 id="volume-source" tabindex="-1">Volume source <a class="header-anchor" href="#volume-source" aria-label="Permalink to &quot;Volume source&quot;">​</a></h4><p>Откуда берётся значение объёма. По умолчанию <strong>Total</strong>.</p><ul><li><strong>Total</strong> — оборот, суммированный по всем включённым биржам.</li><li><strong>Priority</strong> — оборот только с первой биржи в порядке приоритета.</li></ul><h4 id="volume-type" tabindex="-1">Volume type <a class="header-anchor" href="#volume-type" aria-label="Permalink to &quot;Volume type&quot;">​</a></h4><p>Какое окно охватывает значение объёма. По умолчанию <strong>75m</strong>.</p><ul><li><strong>75m</strong> — скользящий объём за 75 минут.</li><li><strong>5m</strong> — объём текущей 5-минутной свечи.</li></ul><div class="warning custom-block"><p class="custom-block-title">Эта настройка также выбирает, какой фильтр объёма действует</p><p>У Monitor два ползунка минимального объёма, и <strong>работает только тот, что соответствует текущему Volume type</strong>:</p><ul><li>Volume type <strong>75m</strong> → список фильтрует ползунок <strong>Min volume (75m)</strong>.</li><li>Volume type <strong>5m</strong> → список фильтрует ползунок <strong>Min volume (5m)</strong>.</li></ul><p>Второй ползунок сохраняет своё значение, но не действует. Если вы выставили фильтр и не видите результата — проверьте, соответствует ли Volume type тому ползунку, который вы двигали. Надпись <code>min $…</code> в заголовке всегда показывает тот, что действует на самом деле.</p></div><h4 id="min-volume-75m" tabindex="-1">Min volume (75m) <a class="header-anchor" href="#min-volume-75m" aria-label="Permalink to &quot;Min volume (75m)&quot;">​</a></h4><p>Исключает тикеры с объёмом за 75 минут ниже этого значения. Диапазон <strong>от $0 до $100M</strong> с шагом $1M, по умолчанию 0 — показывается как <code>None</code>, то есть без фильтрации.</p><h4 id="min-volume-5m" tabindex="-1">Min volume (5m) <a class="header-anchor" href="#min-volume-5m" aria-label="Permalink to &quot;Min volume (5m)&quot;">​</a></h4><p>Исключает тикеры с объёмом текущей 5-минутной свечи ниже этого значения. Диапазон <strong>от $0 до $10M</strong> с шагом $100K, по умолчанию 0 (<code>None</code>).</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>Сколько карточек тикеров показывать. Диапазон <strong>от 3 до 30</strong>, по умолчанию 12. Список переранжируется на лету при изменении.</p><h3 id="metric-colors" tabindex="-1">Metric colors <a class="header-anchor" href="#metric-colors" aria-label="Permalink to &quot;Metric colors&quot;">​</a></h3><p>У двух метрик настраиваемые динамические цвета: <strong>NATR</strong> и <strong>% Change</strong>. У каждой есть главный переключатель, два порога и цвета для текста, контура и фона.</p><h4 id="natr-color" tabindex="-1">NATR color <a class="header-anchor" href="#natr-color" aria-label="Permalink to &quot;NATR color&quot;">​</a></h4><p>Главный переключатель динамической окраски NATR. По умолчанию включено. Выключено — NATR вместо этого просто подсвечивается при пересечении порога оповещения.</p><table tabindex="0"><thead><tr><th>Настройка</th><th>Что делает</th><th>Диапазон</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Level 1 threshold</strong></td><td>NATR выше этого использует цвет 1</td><td>1–10%, шаг 0.5</td><td>3% (<code>#A082E8</code>)</td></tr><tr><td><strong>Level 2 threshold</strong></td><td>NATR выше этого использует цвет 2</td><td>1.5–10%, шаг 0.5</td><td>фактически 7% (<code>#FFA040</code>)</td></tr><tr><td><strong>Outline</strong></td><td>Цвет рамки для каждого уровня плюс переключатель</td><td>—</td><td>выключено</td></tr><tr><td><strong>Background</strong></td><td>Цвет заливки для каждого уровня плюс переключатель</td><td>—</td><td>выключено</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Уровень 2 прибавляется к уровню 1</p><p>Значение рядом с ползунком Level 2 — это <strong>Level 1 + Level 2</strong>, а не собственное значение ползунка. При Level 1 на 3% и ползунке Level 2 на 4% надпись показывает <strong>7.0%</strong> — именно там на самом деле начинается цвет 2.</p><p>То же самое касается ползунка Level 2 для % Change. Читайте надпись, а не ползунок.</p></div><p>Outline и Background — отдельные переключатели со своими цветами уровней 1 и 2, так что можно иметь только цветной текст, цветную рамку, залитую карточку или любую комбинацию.</p><div class="tip custom-block"><p class="custom-block-title">Каждый из этих цветов может быть полупрозрачным</p><p>Все четырнадцать цветовых слотов здесь используют ту же палитру, что и остальное приложение, а в ней есть ползунок непрозрачности. Непрозрачность хранится внутри hex, так что полупрозрачное значение состоит из 8 символов (<code>#rrggbbaa</code>), а не 6 — см. <a href="/manual/ru/customize/chart-colors.html#палитра">палитру</a>.</p><p>Больше всего это важно для заливки фона: при полной непрозрачности залитая карточка перекрывает строку под собой, а примерно на 15–25% лишь подкрашивает её.</p></div><h4 id="change-direction" tabindex="-1">% Change direction <a class="header-anchor" href="#change-direction" aria-label="Permalink to &quot;% Change direction&quot;">​</a></h4><p>Главный переключатель динамической окраски % Change. По умолчанию включено.</p><p>Работает как NATR, но с <strong>двумя цветами на уровень</strong> — один для роста, другой для падения:</p><table tabindex="0"><thead><tr><th>Настройка</th><th>Диапазон</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Level 1 threshold</strong></td><td>1–10%, шаг 0.5</td><td>2% — рост <code>#4CAF50</code>, падение <code>#E05555</code></td></tr><tr><td><strong>Level 2 threshold</strong></td><td>1.5–10%, шаг 0.5</td><td>фактически 5% — рост <code>#00E676</code>, падение <code>#FF5252</code></td></tr><tr><td><strong>Outline</strong></td><td>—</td><td>выключено</td></tr><tr><td><strong>Background</strong></td><td>—</td><td>выключено</td></tr></tbody></table><h3 id="иконки-бирж" tabindex="-1">Иконки бирж <a class="header-anchor" href="#иконки-бирж" aria-label="Permalink to &quot;Иконки бирж&quot;">​</a></h3><h4 id="show-icons" tabindex="-1">Show icons <a class="header-anchor" href="#show-icons" aria-label="Permalink to &quot;Show icons&quot;">​</a></h4><p>Показывает или скрывает логотипы бирж на карточках тикеров. По умолчанию включено.</p><h3 id="exchanges" tabindex="-1">Exchanges <a class="header-anchor" href="#exchanges" aria-label="Permalink to &quot;Exchanges&quot;">​</a></h3><p>Один список с перетаскиванием отвечает и за приоритет, и за включение, и разделён линией:</p><ul><li><strong>Выше разделителя</strong> — включённые, пронумерованные по рангу. Ранг важен для вариантов <code>Priority</code> в NATR aggregation и Volume source.</li><li><strong>Ниже разделителя</strong> — выключенные. Их ранг показан как <code>—</code>, и они не дают никаких данных.</li></ul><p>Перетащите биржу через разделитель, чтобы включить или выключить её. По умолчанию порядок такой: <strong>Binance, Bybit, OKX, Gate.io, Hyperliquid</strong>, причём <strong>Gate.io выключен</strong> — перетащите его выше разделителя, чтобы включить.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Порядок приоритета по умолчанию в Monitor отличается от Knives (<code>Bybit, Binance, Gate.io, OKX, Hyperliquid</code>). У этих двух инструментов отдельные списки приоритета — изменение порядка в одном не влияет на другой.</p></div><h3 id="alerts" tabindex="-1">Alerts <a class="header-anchor" href="#alerts" aria-label="Permalink to &quot;Alerts&quot;">​</a></h3><h4 id="alert-sound" tabindex="-1">Alert sound <a class="header-anchor" href="#alert-sound" aria-label="Permalink to &quot;Alert sound&quot;">​</a></h4><p>Воспроизводит звук, когда тикер достигает порога NATR или % Change ниже. По умолчанию включено. Когда выключено, надпись порогов в заголовке приглушена.</p><h4 id="natr-threshold" tabindex="-1">NATR threshold <a class="header-anchor" href="#natr-threshold" aria-label="Permalink to &quot;NATR threshold&quot;">​</a></h4><p>Подсвечивает и оповещает, когда NATR превышает этот процент. Диапазон <strong>от 3% до 20%</strong> с шагом 0.5%, по умолчанию 5%.</p><h4 id="change-threshold" tabindex="-1">% Change threshold <a class="header-anchor" href="#change-threshold" aria-label="Permalink to &quot;% Change threshold&quot;">​</a></h4><p>Подсвечивает и оповещает, когда % изменения превышает это значение. Диапазон <strong>от 3% до 20%</strong> с шагом 0.5%, по умолчанию 4%.</p><div class="info custom-block"><p class="custom-block-title">Пороги и цвета — это две разные системы</p><p>Пороги оповещений здесь решают, когда сработает <em>звук</em>. Уровни <a href="#metric-colors">цветов метрик</a> решают, как значение <em>нарисовано</em>. Они настраиваются независимо и могут иметь разные значения — карточка может быть окрашена, не вызвав звука, и наоборот.</p></div><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/tools/knives.html">Knives</a> — лента срабатываний вместо рейтинга</li><li><a href="/manual/ru/tools/analyzer.html">Analyzer</a> — полноценное пространство для графиков</li><li><a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a> — цвета свечей, которые используют графики Monitor</li><li><a href="/manual/ru/customize/majors.html">Слой мажоров</a> — доступен на полноэкранном графике</li></ul>',53))])}const A=l(h,[["render",c]]);export{f as __pageData,A as default};
